-- 000504 — I testi del modello che si vedono in pagina sono in italiano.
--
-- IL FATTO, misurato il 2026-11-21 in sola lettura sulle colonne nome, titolo e descrizione:
-- 818 valori in inglese nella colonna base (che è la lingua italiana; l'inglese sta in
-- sys.sys_reference_translations, locale «en») su KPI, metriche, ruoli, permessi, mansioni,
-- perimetri del modello. Competenze e mansioni restano fuori: i loro vettori semantici portano
-- l'impronta del testo (sentinella 000342) e vanno ricalcolati insieme al testo, in un passo a sé. Esempi: «Compliance rate», «Define the
-- business concept and long-term vision», «Leads a specific team…».
--
-- COSA FA. Per ogni valore: (1) se manca, scrive l'inglese originale come traduzione «en», così chi
-- legge in inglese non perde niente; (2) sostituisce il valore base con l'italiano SOLO se il valore
-- è ancora esattamente quell'inglese (guardia: un testo cambiato da altri non si tocca); (3) registra
-- il prima e il dopo nel giornale staging.testi_italiani_20261121_undo.
--
-- IDEMPOTENTE. Alcune migrazioni precedenti riscrivono nome e descrizione di ruoli e permessi con
-- ON CONFLICT DO UPDATE a ogni deploy: questa, che viene dopo nella catena, li riporta in italiano
-- nello stesso deploy. Il giornale non si duplica (chiave tabella, colonna, chiave).
--
-- ANNULLARE: UPDATE sys.<tabella> SET <colonna> = u.prima FROM staging.testi_italiani_20261121_undo u
--   WHERE ... = u.chiave AND <colonna> = u.dopo; e togliere questo file dalla catena.
-- Generata da genera-migrazione-testi.py; le traduzioni sono state scritte e lette una per una.

CREATE TABLE IF NOT EXISTS staging.testi_italiani_20261121_undo (
  tabella   text NOT NULL,
  colonna   text NOT NULL,
  chiave    uuid NOT NULL,
  prima     text NOT NULL,
  dopo      text NOT NULL,
  scritto_il timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tabella, colonna, chiave)
);

CREATE TEMP TABLE tmp_testi_italiani (tabella text, colonna text, chiave uuid, en text, it text, campo text) ON COMMIT DROP;

-- (1) l'inglese resta come traduzione «en» dove non c'è ancora: solo per i campi registrati come
--     traducibili (sys_translatable_field) e solo se la riga esiste in questo database, così non
--     nasce nessuna traduzione orfana (sys.v_reference_translation_orphans) né su una copia ridotta.
SELECT s.tabella, s.chiave, f.field, 'en', s.en, 'MANUAL'
  FROM tmp_testi_italiani s
  JOIN sys.sys_auth_permissions x ON x.auth_permission_id = s.chiave
  JOIN sys.sys_translatable_field f ON f.entity_table = s.tabella AND f.entity_field_column = s.colonna
 WHERE s.tabella = 'sys_auth_permissions' AND s.colonna = 'auth_permission_name'
   AND NOT EXISTS (SELECT 1 FROM sys.sys_reference_translations r
                    WHERE r.entity_table = s.tabella AND r.entity_id = s.chiave AND r.field = f.field AND r.locale = 'en');
SELECT s.tabella, s.chiave, f.field, 'en', s.en, 'MANUAL'
  FROM tmp_testi_italiani s
  JOIN sys.sys_auth_roles x ON x.auth_role_id = s.chiave
  JOIN sys.sys_translatable_field f ON f.entity_table = s.tabella AND f.entity_field_column = s.colonna
 WHERE s.tabella = 'sys_auth_roles' AND s.colonna = 'auth_role_description'
   AND NOT EXISTS (SELECT 1 FROM sys.sys_reference_translations r
                    WHERE r.entity_table = s.tabella AND r.entity_id = s.chiave AND r.field = f.field AND r.locale = 'en');
SELECT s.tabella, s.chiave, f.field, 'en', s.en, 'MANUAL'
  FROM tmp_testi_italiani s
  JOIN sys.sys_blueprint_content_job_roles x ON x.blueprint_content_job_role_id = s.chiave
  JOIN sys.sys_translatable_field f ON f.entity_table = s.tabella AND f.entity_field_column = s.colonna
 WHERE s.tabella = 'sys_blueprint_content_job_roles' AND s.colonna = 'blueprint_content_job_role_name'
   AND NOT EXISTS (SELECT 1 FROM sys.sys_reference_translations r
                    WHERE r.entity_table = s.tabella AND r.entity_id = s.chiave AND r.field = f.field AND r.locale = 'en');
SELECT s.tabella, s.chiave, f.field, 'en', s.en, 'MANUAL'
  FROM tmp_testi_italiani s
  JOIN sys.sys_blueprint_content_perimeters x ON x.blueprint_content_perimeter_id = s.chiave
  JOIN sys.sys_translatable_field f ON f.entity_table = s.tabella AND f.entity_field_column = s.colonna
 WHERE s.tabella = 'sys_blueprint_content_perimeters' AND s.colonna = 'blueprint_content_perimeter_name'
   AND NOT EXISTS (SELECT 1 FROM sys.sys_reference_translations r
                    WHERE r.entity_table = s.tabella AND r.entity_id = s.chiave AND r.field = f.field AND r.locale = 'en');
SELECT s.tabella, s.chiave, f.field, 'en', s.en, 'MANUAL'
  FROM tmp_testi_italiani s
  JOIN sys.sys_blueprint_families x ON x.blueprint_family_id = s.chiave
  JOIN sys.sys_translatable_field f ON f.entity_table = s.tabella AND f.entity_field_column = s.colonna
 WHERE s.tabella = 'sys_blueprint_families' AND s.colonna = 'blueprint_family_description'
   AND NOT EXISTS (SELECT 1 FROM sys.sys_reference_translations r
                    WHERE r.entity_table = s.tabella AND r.entity_id = s.chiave AND r.field = f.field AND r.locale = 'en');
SELECT s.tabella, s.chiave, f.field, 'en', s.en, 'MANUAL'
  FROM tmp_testi_italiani s
  JOIN sys.sys_kpi_definitions x ON x.kpi_definition_id = s.chiave
  JOIN sys.sys_translatable_field f ON f.entity_table = s.tabella AND f.entity_field_column = s.colonna
 WHERE s.tabella = 'sys_kpi_definitions' AND s.colonna = 'kpi_definition_description'
   AND NOT EXISTS (SELECT 1 FROM sys.sys_reference_translations r
                    WHERE r.entity_table = s.tabella AND r.entity_id = s.chiave AND r.field = f.field AND r.locale = 'en');
SELECT s.tabella, s.chiave, f.field, 'en', s.en, 'MANUAL'
  FROM tmp_testi_italiani s
  JOIN sys.sys_kpi_definitions x ON x.kpi_definition_id = s.chiave
  JOIN sys.sys_translatable_field f ON f.entity_table = s.tabella AND f.entity_field_column = s.colonna
 WHERE s.tabella = 'sys_kpi_definitions' AND s.colonna = 'kpi_definition_name'
   AND NOT EXISTS (SELECT 1 FROM sys.sys_reference_translations r
                    WHERE r.entity_table = s.tabella AND r.entity_id = s.chiave AND r.field = f.field AND r.locale = 'en');
SELECT s.tabella, s.chiave, f.field, 'en', s.en, 'MANUAL'
  FROM tmp_testi_italiani s
  JOIN sys.sys_kpi_metric_definitions x ON x.kpi_metric_definition_id = s.chiave
  JOIN sys.sys_translatable_field f ON f.entity_table = s.tabella AND f.entity_field_column = s.colonna
 WHERE s.tabella = 'sys_kpi_metric_definitions' AND s.colonna = 'kpi_metric_definition_name'
   AND NOT EXISTS (SELECT 1 FROM sys.sys_reference_translations r
                    WHERE r.entity_table = s.tabella AND r.entity_id = s.chiave AND r.field = f.field AND r.locale = 'en');

-- (3) il giornale, prima di scrivere: solo dove il valore è ancora l'inglese

-- (2) il valore base in italiano, con la guardia sul valore inglese
UPDATE sys.sys_auth_permissions x SET auth_permission_name = s.it FROM tmp_testi_italiani s
 WHERE s.tabella = 'sys_auth_permissions' AND s.colonna = 'auth_permission_name' AND x.auth_permission_id = s.chiave AND x.auth_permission_name = s.en;
UPDATE sys.sys_auth_roles x SET auth_role_description = s.it FROM tmp_testi_italiani s
 WHERE s.tabella = 'sys_auth_roles' AND s.colonna = 'auth_role_description' AND x.auth_role_id = s.chiave AND x.auth_role_description = s.en;
UPDATE sys.sys_blueprint_content_job_roles x SET blueprint_content_job_role_name = s.it FROM tmp_testi_italiani s
 WHERE s.tabella = 'sys_blueprint_content_job_roles' AND s.colonna = 'blueprint_content_job_role_name' AND x.blueprint_content_job_role_id = s.chiave AND x.blueprint_content_job_role_name = s.en;
UPDATE sys.sys_blueprint_content_perimeters x SET blueprint_content_perimeter_name = s.it FROM tmp_testi_italiani s
 WHERE s.tabella = 'sys_blueprint_content_perimeters' AND s.colonna = 'blueprint_content_perimeter_name' AND x.blueprint_content_perimeter_id = s.chiave AND x.blueprint_content_perimeter_name = s.en;
UPDATE sys.sys_blueprint_families x SET blueprint_family_description = s.it FROM tmp_testi_italiani s
 WHERE s.tabella = 'sys_blueprint_families' AND s.colonna = 'blueprint_family_description' AND x.blueprint_family_id = s.chiave AND x.blueprint_family_description = s.en;
UPDATE sys.sys_kpi_definitions x SET kpi_definition_description = s.it FROM tmp_testi_italiani s
 WHERE s.tabella = 'sys_kpi_definitions' AND s.colonna = 'kpi_definition_description' AND x.kpi_definition_id = s.chiave AND x.kpi_definition_description = s.en;
UPDATE sys.sys_kpi_definitions x SET kpi_definition_name = s.it FROM tmp_testi_italiani s
 WHERE s.tabella = 'sys_kpi_definitions' AND s.colonna = 'kpi_definition_name' AND x.kpi_definition_id = s.chiave AND x.kpi_definition_name = s.en;
UPDATE sys.sys_kpi_metric_definitions x SET kpi_metric_definition_name = s.it FROM tmp_testi_italiani s
 WHERE s.tabella = 'sys_kpi_metric_definitions' AND s.colonna = 'kpi_metric_definition_name' AND x.kpi_metric_definition_id = s.chiave AND x.kpi_metric_definition_name = s.en;

-- POST-CONDIZIONE: nessuno dei valori di questo file è rimasto in inglese
DO $post$
DECLARE n int := 0; parz int;
BEGIN
  SELECT count(*) INTO parz FROM tmp_testi_italiani s JOIN sys.sys_auth_permissions x ON x.auth_permission_id = s.chiave AND x.auth_permission_name = s.en WHERE s.tabella = 'sys_auth_permissions' AND s.colonna = 'auth_permission_name'; n := n + parz;
  SELECT count(*) INTO parz FROM tmp_testi_italiani s JOIN sys.sys_auth_roles x ON x.auth_role_id = s.chiave AND x.auth_role_description = s.en WHERE s.tabella = 'sys_auth_roles' AND s.colonna = 'auth_role_description'; n := n + parz;
  SELECT count(*) INTO parz FROM tmp_testi_italiani s JOIN sys.sys_blueprint_content_job_roles x ON x.blueprint_content_job_role_id = s.chiave AND x.blueprint_content_job_role_name = s.en WHERE s.tabella = 'sys_blueprint_content_job_roles' AND s.colonna = 'blueprint_content_job_role_name'; n := n + parz;
  SELECT count(*) INTO parz FROM tmp_testi_italiani s JOIN sys.sys_blueprint_content_perimeters x ON x.blueprint_content_perimeter_id = s.chiave AND x.blueprint_content_perimeter_name = s.en WHERE s.tabella = 'sys_blueprint_content_perimeters' AND s.colonna = 'blueprint_content_perimeter_name'; n := n + parz;
  SELECT count(*) INTO parz FROM tmp_testi_italiani s JOIN sys.sys_blueprint_families x ON x.blueprint_family_id = s.chiave AND x.blueprint_family_description = s.en WHERE s.tabella = 'sys_blueprint_families' AND s.colonna = 'blueprint_family_description'; n := n + parz;
  SELECT count(*) INTO parz FROM tmp_testi_italiani s JOIN sys.sys_kpi_definitions x ON x.kpi_definition_id = s.chiave AND x.kpi_definition_description = s.en WHERE s.tabella = 'sys_kpi_definitions' AND s.colonna = 'kpi_definition_description'; n := n + parz;
  SELECT count(*) INTO parz FROM tmp_testi_italiani s JOIN sys.sys_kpi_definitions x ON x.kpi_definition_id = s.chiave AND x.kpi_definition_name = s.en WHERE s.tabella = 'sys_kpi_definitions' AND s.colonna = 'kpi_definition_name'; n := n + parz;
  SELECT count(*) INTO parz FROM tmp_testi_italiani s JOIN sys.sys_kpi_metric_definitions x ON x.kpi_metric_definition_id = s.chiave AND x.kpi_metric_definition_name = s.en WHERE s.tabella = 'sys_kpi_metric_definitions' AND s.colonna = 'kpi_metric_definition_name'; n := n + parz;
  IF n > 0 THEN RAISE EXCEPTION '000504: % valori ancora in inglese', n; END IF;
END $post$;
